<h2>Backsolve SDR activity goals</h2><p class="lead">Translate a meeting target into required conversations and outbound activities using funnel conversion rates.</p><div class="notice">“Activity” can mean calls, personalized emails or another defined outreach unit. Do not sum unlike activities without a clear model of how each converts.</div><div class="form-grid"><div class="field"><label for="meet">Target completed meetings per month</label><input id="meet" type="number" value="20" min="0" step="any"></div><div class="field"><label for="convmeet">Conversation → meeting rate (%)</label><input id="convmeet" type="number" value="25" min="0.001" max="100" step="any"></div><div class="field"><label for="actconv">Activity → live conversation rate (%)</label><input id="actconv" type="number" value="8" min="0.001" max="100" step="any"></div><div class="field"><label for="days">Working days in month</label><input id="days" type="number" value="20" min="1" step="1"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Conversations needed</span><strong id="conv">—</strong></div><div class="metric"><span>Activities needed</span><strong id="acts">—</strong></div><div class="metric"><span>Activities per working day</span><strong id="perday">—</strong></div><div class="metric"><span>Meetings per working day</span><strong id="meetday">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('conv').textContent='—';$('acts').textContent='—';$('perday').textContent='—';$('meetday').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const m=num('meet'),cm=num('convmeet')/100,ac=num('actconv')/100,d=num('days');if(!(m>=0&&cm>0&&cm<=1&&ac>0&&ac<=1&&d>0))throw 0;const c=m/cm,a=c/ac;$('conv').textContent=fmt(Math.ceil(c),0);$('acts').textContent=fmt(Math.ceil(a),0);$('perday').textContent=fmt(a/d,1);$('meetday').textContent=fmt(m/d,2);$('note').textContent='Activity quality and channel mix matter. Use conversion rates from comparable SDRs/segments rather than applying one benchmark universally.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
